/* PROTOTYPE: visual study only. The geometry favors comparison over production reuse. */

:root {
  color-scheme: dark;
  --ghost-bg: 41 41 41;
  --ghost-fg: #d6d6d6;
  --black: #111111;
  --red: #ff6b6b;
  --green: #4dff88;
  --yellow: #ffe66d;
  --blue: #66b3ff;
  --magenta: #ff7bf1;
  --cyan: #5efcff;
  --white: #f0f0f0;
  --bright-black: #777777;
  --bright-red: #ff8f8f;
  --bright-green: #72ffad;
  --bright-yellow: #fff18f;
  --bright-blue: #8ac7ff;
  --bright-magenta: #ff9bf5;
  --bright-cyan: #8dffff;
  --bright-white: #ffffff;
  --claude: #e87951;
  --claude-soft: #f0a17f;
  --line: rgba(214, 214, 214, 0.18);
  --muted: #86868c;
  --dim: #66666c;
  --terminal-font: "Iosevka Term", "Sarasa Term SC", "SFMono-Regular", "Cascadia Mono", monospace;
  font-family: var(--terminal-font);
  font-synthesis: none;
  text-rendering: geometricPrecision;
}

* {
  box-sizing: border-box;
}

html,
body,
#app {
  min-width: 320px;
  min-height: 100%;
  margin: 0;
}

body {
  min-height: 100vh;
  overflow: hidden;
  background: #151517;
  color: var(--ghost-fg);
}

button,
[contenteditable] {
  font: inherit;
}

button {
  color: inherit;
}

.prototype-page {
  position: relative;
  display: grid;
  min-height: 100vh;
  place-items: center;
  padding: 34px 28px 98px;
  isolation: isolate;
  overflow: hidden;
}

.wallpaper {
  position: fixed;
  inset: -80px;
  z-index: -3;
  overflow: hidden;
  background:
    radial-gradient(circle at 12% 72%, rgba(67, 86, 174, 0.72), transparent 32%),
    radial-gradient(circle at 78% 15%, rgba(111, 76, 150, 0.72), transparent 31%),
    linear-gradient(128deg, #20202a 0%, #1a1d24 42%, #302330 100%);
}

.wallpaper span {
  position: absolute;
  width: 34vw;
  aspect-ratio: 1;
  border-radius: 48% 52% 61% 39%;
  filter: blur(58px);
  opacity: 0.38;
  animation: drift 18s ease-in-out infinite alternate;
}

.wallpaper span:nth-child(1) {
  top: -8%;
  left: 17%;
  background: #9a5ab1;
}

.wallpaper span:nth-child(2) {
  right: -5%;
  bottom: 2%;
  background: #1b89a0;
  animation-delay: -6s;
}

.wallpaper span:nth-child(3) {
  bottom: -28%;
  left: 28%;
  background: #be774a;
  animation-delay: -11s;
}

@keyframes drift {
  to {
    translate: 7vw 4vh;
    rotate: 12deg;
  }
}

.prototype-caption {
  position: fixed;
  top: 10px;
  left: 50%;
  display: flex;
  width: min(1640px, calc(100vw - 56px));
  justify-content: space-between;
  translate: -50% 0;
  color: rgba(255, 255, 255, 0.56);
  font: 600 10px/1.2 ui-sans-serif, system-ui, sans-serif;
  letter-spacing: 0.12em;
}

.state-readout {
  color: rgba(255, 255, 255, 0.38);
  font-weight: 500;
  letter-spacing: 0.04em;
  text-transform: none;
}

.ghostty-window {
  width: min(1640px, calc(100vw - 56px));
  height: min(870px, calc(100vh - 132px));
  min-height: 610px;
  overflow: hidden;
  border: 1px solid rgba(255, 255, 255, 0.13);
  border-radius: 13px;
  background: rgba(var(--ghost-bg) / 0.85);
  box-shadow:
    0 38px 90px rgba(0, 0, 0, 0.5),
    0 4px 16px rgba(0, 0, 0, 0.32),
    inset 0 1px rgba(255, 255, 255, 0.08);
  backdrop-filter: blur(50px) saturate(118%);
  -webkit-backdrop-filter: blur(50px) saturate(118%);
}

.ghostty-titlebar {
  position: relative;
  display: grid;
  height: 37px;
  grid-template-columns: 1fr auto 1fr;
  align-items: center;
  border-bottom: 1px solid rgba(255, 255, 255, 0.1);
  background: rgba(29, 29, 31, 0.74);
  color: rgba(240, 240, 240, 0.72);
  font: 500 12px/1 ui-sans-serif, system-ui, sans-serif;
  -webkit-user-select: none;
  user-select: none;
}

.traffic-lights {
  display: flex;
  gap: 8px;
  padding-left: 13px;
}

.traffic-lights span {
  width: 11px;
  height: 11px;
  border-radius: 50%;
  box-shadow: inset 0 0 0 0.5px rgba(0, 0, 0, 0.32);
}

.traffic-lights span:nth-child(1) { background: #ff5f57; }
.traffic-lights span:nth-child(2) { background: #febc2e; }
.traffic-lights span:nth-child(3) { background: #28c840; }

.ghostty-tab {
  display: flex;
  align-items: center;
  gap: 7px;
}

.tab-icon {
  color: var(--bright-black);
}

.window-action {
  justify-self: end;
  margin-right: 13px;
  padding: 1px 3px;
  border-radius: 3px;
  background: #0789ff;
  color: #111111;
  font-size: 9px;
  font-weight: 800;
}

.ghostty-screen {
  height: calc(100% - 37px);
  font-family: var(--terminal-font);
  font-size: clamp(14px, 1.05vw, 19px);
  font-weight: 500;
  line-height: 1.42;
  letter-spacing: 0;
}

.terminal-view {
  display: grid;
  height: 100%;
  min-height: 0;
  overflow: hidden;
}

.terminal-scroll {
  min-height: 0;
  overflow: auto;
  scrollbar-width: thin;
  scrollbar-color: rgba(255, 255, 255, 0.15) transparent;
}

.terminal-scroll::-webkit-scrollbar { width: 5px; }
.terminal-scroll::-webkit-scrollbar-thumb { background: rgba(255, 255, 255, 0.14); }

.muted { color: var(--muted); }
.cyan { color: var(--cyan); }
.magenta { color: var(--magenta); }
.orange { color: var(--claude); }
.success { color: var(--green); }
.danger { color: var(--red); }
.key { color: var(--white); }
.path { color: #b9b9be; }
.bullet { color: var(--bright-black); }
.tree { color: #64646a; margin-right: 1ch; }
.chevron { margin-left: auto; color: var(--muted); }
.footer-spacer { flex: 1; }

.tool-cluster {
  display: flex;
  width: 100%;
  align-items: center;
  gap: 1ch;
  padding: 0;
  border: 0;
  background: transparent;
  text-align: left;
  cursor: pointer;
}

.tool-cluster:hover strong,
.tool-cluster:focus-visible strong {
  text-decoration: underline;
  text-underline-offset: 3px;
}

.composer-input {
  min-width: 0;
  outline: 0;
  white-space: pre-wrap;
  overflow-wrap: anywhere;
  caret-color: var(--white);
}

.composer-input:empty::before {
  color: #717177;
  content: attr(data-placeholder);
  pointer-events: none;
}

/* Codex direction */

.codex-view {
  grid-template-rows: minmax(0, 1fr) auto;
  background: transparent;
}

.codex-transcript {
  padding: 17px 20px 24px;
}

.codex-header {
  width: fit-content;
  min-width: min(690px, 82%);
  margin: 0 0 22px;
  padding: 10px 15px 11px;
  border: 1px solid #717177;
  background: rgba(255, 255, 255, 0.008);
  box-shadow: inset 0 0 0 1px rgba(0, 0, 0, 0.24);
}

.codex-brand {
  margin-bottom: 10px;
  color: var(--ghost-fg);
}

.codex-mark {
  margin-right: 1ch;
  color: #8e8e94;
}

.codex-header-grid {
  display: grid;
  grid-template-columns: max-content max-content max-content max-content;
  gap: 0 2ch;
}

.codex-system-row,
.codex-answer {
  display: flex;
  gap: 1ch;
  margin-bottom: 18px;
}

.codex-system-row {
  color: #c6c6ca;
}

.codex-tip {
  margin: 0 0 20px 2ch;
}

.codex-user {
  display: flex;
  min-height: 57px;
  align-items: flex-start;
  gap: 1ch;
  margin: 0 -20px 22px;
  padding: 12px 20px;
  background: rgba(255, 255, 255, 0.12);
  color: #eeeeef;
}

.prompt-glyph {
  color: #9a9aa1;
}

.codex-answer > div {
  max-width: 112ch;
}

.codex-answer.final {
  margin-top: 3px;
}

.codex-tool-toggle {
  margin-bottom: 5px;
}

.tool-count {
  color: var(--muted);
}

.codex-tool-lines {
  display: grid;
  gap: 1px;
  margin: 0 0 18px 2ch;
  color: #bcbcc1;
}

.codex-section-title {
  display: flex;
  gap: 1ch;
  margin-bottom: 5px;
}

.codex-diff {
  margin: 0 -20px 19px;
  color: var(--muted);
}

.codex-diff > div {
  display: grid;
  min-height: 1.42em;
  grid-template-columns: 6ch minmax(0, 1fr);
  padding: 0 20px;
}

.codex-diff > div > span:first-child {
  color: #85858a;
  text-align: right;
  padding-right: 2ch;
}

.diff-context { color: #77777d; }
.diff-removed { color: var(--red); }
.diff-added { color: var(--green); }

.codex-diff .diff-removed {
  background: #4a221d;
}

.codex-diff .diff-added {
  background: #213a2b;
}

.codex-answer p,
.hybrid-answer p {
  margin: 3px 0 0;
  color: #bbbbc0;
}

.submitted-line {
  margin: 12px 0 0;
  padding: 8px 10px;
  background: rgba(255, 255, 255, 0.06);
}

.codex-submitted {
  margin-inline: -20px;
  padding-inline: 20px;
  background: rgba(255, 255, 255, 0.12);
}

.codex-bottom {
  padding: 0;
}

.codex-composer {
  display: grid;
  min-height: 72px;
  grid-template-columns: 2ch minmax(0, 1fr);
  align-items: start;
  gap: 0.5ch;
  padding: 13px 20px;
  background: rgba(255, 255, 255, 0.12);
  color: var(--white);
}

.codex-footer {
  display: flex;
  min-height: 36px;
  align-items: start;
  gap: 1ch;
  padding: 5px 20px 9px;
  color: #77777d;
  font-size: 0.88em;
  white-space: nowrap;
}

.codex-model,
.codex-fast { color: #ffe7ae; }
.codex-path { color: #a8ecad; }
.codex-context { color: #f4ac87; }
.codex-weekly { color: #ec8fb8; }
.status-separator { color: #77777d; }

/* Claude direction */

.claude-view {
  grid-template-rows: minmax(0, 1fr) auto;
  background: transparent;
}

.claude-transcript {
  padding: 18px 20px 24px;
}

.claude-header {
  position: relative;
  display: grid;
  min-height: 205px;
  grid-template-columns: minmax(310px, 35%) minmax(0, 65%);
  margin: 6px 0 30px;
  border: 1px solid var(--claude);
  color: var(--ghost-fg);
}

.claude-header-label {
  position: absolute;
  z-index: 1;
  top: -0.84em;
  left: 4ch;
  display: flex;
  gap: 1ch;
  padding: 0 1ch;
  background: #292929;
  color: var(--claude);
}

.claude-header-label span {
  color: #96969b;
}

.claude-welcome-left {
  display: grid;
  place-content: center;
  gap: 4px;
  padding: 25px 18px 16px;
  text-align: center;
}

.claude-mascot {
  margin: 9px 0 8px;
  color: var(--claude);
  font: 700 1.2em/0.78 var(--terminal-font);
  letter-spacing: -0.08em;
}

.claude-welcome-right {
  display: grid;
  grid-template-rows: auto 1fr;
  border-left: 1px solid var(--claude);
}

.claude-welcome-right section {
  min-width: 0;
  padding: 11px 16px;
  overflow: hidden;
}

.claude-welcome-right section + section {
  border-top: 1px solid var(--claude);
}

.claude-welcome-right strong {
  color: var(--claude);
}

.claude-welcome-right section > div {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.claude-user {
  display: flex;
  min-height: 42px;
  align-items: flex-start;
  gap: 1ch;
  margin: 0 -20px 20px;
  padding: 8px 20px;
  background: rgba(255, 255, 255, 0.1);
  color: #eeeeef;
}

.claude-prompt,
.claude-dot {
  color: var(--white);
}

.claude-message {
  display: grid;
  max-width: 112ch;
  grid-template-columns: 2ch minmax(0, 1fr);
  gap: 0.5ch;
  margin-bottom: 17px;
}

.claude-message.final {
  margin-top: 20px;
}

.claude-thought {
  display: flex;
  gap: 1ch;
  margin: 0 0 16px;
}

.claude-tool-toggle {
  width: auto;
  max-width: 100%;
  margin-bottom: 4px;
}

.claude-action-dot {
  color: var(--claude);
}

.claude-tool-tree {
  display: grid;
  gap: 1px;
  margin: 0 0 18px 3ch;
  color: #a8a8ae;
}

.claude-tool-call {
  margin-bottom: 18px;
}

.claude-tool-call > div:first-child {
  display: flex;
  gap: 1ch;
}

.claude-diff {
  width: min(94ch, calc(100% - 3ch));
  margin: 7px 0 5px 3ch;
}

.claude-diff > div {
  display: grid;
  grid-template-columns: 5ch minmax(0, 1fr);
  padding-inline: 1ch;
}

.claude-diff > div > span:first-child {
  color: #77777d;
  text-align: right;
  padding-right: 1.5ch;
}

.claude-diff .diff-removed { background: rgba(74, 34, 29, 0.82); }
.claude-diff .diff-added { background: rgba(33, 58, 43, 0.82); }

.claude-result {
  margin-left: 3ch;
}

.claude-submitted {
  border-left: 0;
}

.claude-bottom {
  padding: 0 0 10px;
}

.claude-effort {
  min-height: 28px;
  padding: 0 24px 5px;
  color: #909095;
  text-align: right;
}

.claude-effort > span:first-child {
  font-size: 0.75em;
}

.claude-composer {
  display: grid;
  min-height: 68px;
  grid-template-columns: 2ch minmax(0, 1fr);
  gap: 0.5ch;
  padding: 11px 20px;
  border-top: 1px solid rgba(214, 214, 214, 0.42);
  border-bottom: 1px solid rgba(214, 214, 214, 0.42);
}

.claude-footer {
  display: flex;
  gap: 1ch;
  padding: 7px 24px 0;
  color: #85858a;
  font-size: 0.9em;
  white-space: nowrap;
}

.permission-mode {
  color: var(--yellow);
}

/* Hybrid direction */

.hybrid-view {
  grid-template-rows: auto minmax(0, 1fr) auto;
  background:
    linear-gradient(90deg, rgba(94, 252, 255, 0.022), transparent 34%),
    rgba(19, 19, 22, 0.36);
}

.hybrid-header {
  display: grid;
  grid-template-columns: 1fr auto 1fr;
  align-items: center;
  min-height: 48px;
  padding: 0 17px;
  border-bottom: 1px solid rgba(255, 255, 255, 0.1);
  background: rgba(17, 17, 17, 0.23);
  font-size: 0.9em;
}

.hybrid-brand,
.hybrid-header-center,
.hybrid-header-right {
  display: flex;
  align-items: center;
  gap: 1ch;
}

.hybrid-header-right {
  justify-self: end;
}

.pi-mark {
  color: var(--cyan);
  font-weight: 700;
}

.pi-mark.small {
  font-size: 1.25em;
}

.hybrid-badge,
.composer-chip {
  padding: 0 0.8ch;
  border: 1px solid rgba(94, 252, 255, 0.35);
  border-radius: 2px;
  color: var(--bright-cyan);
  font-size: 0.75em;
  text-transform: uppercase;
}

.status-dot {
  display: inline-block;
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: var(--green);
  box-shadow: 0 0 9px rgba(77, 255, 136, 0.55);
}

.hybrid-body {
  display: grid;
  min-height: 0;
  grid-template-columns: minmax(0, 1fr) minmax(225px, 19%);
}

.hybrid-transcript {
  padding: 18px 20px 22px;
}

.hybrid-user {
  display: flex;
  gap: 1ch;
  margin-bottom: 18px;
  padding: 10px 12px;
  border-left: 2px solid var(--cyan);
  background: rgba(255, 255, 255, 0.075);
}

.trace-block {
  display: grid;
  max-width: 105ch;
  grid-template-columns: 2ch 1fr;
  margin-bottom: 17px;
}

.trace-rail {
  position: relative;
}

.trace-rail::after {
  position: absolute;
  top: 10px;
  bottom: -15px;
  left: 4px;
  width: 1px;
  background: rgba(94, 252, 255, 0.25);
  content: "";
}

.trace-node {
  position: relative;
  z-index: 1;
  display: block;
  width: 9px;
  height: 9px;
  margin-top: 7px;
  border: 2px solid rgba(41, 41, 41, 0.95);
  border-radius: 50%;
}

.cyan-bg { background: var(--cyan); }

.trace-heading {
  display: flex;
  gap: 2ch;
}

.trace-content p {
  margin: 3px 0 0;
  color: #a8a8ae;
}

.hybrid-tool-card {
  display: grid;
  width: min(100%, 108ch);
  grid-template-columns: 3ch 1fr auto 2ch;
  align-items: center;
  gap: 1ch;
  margin-bottom: 7px;
  padding: 8px 10px;
  border: 1px solid rgba(102, 179, 255, 0.18);
  background: rgba(102, 179, 255, 0.055);
  text-align: left;
  cursor: pointer;
}

.hybrid-tool-card small {
  display: block;
  color: var(--muted);
  font-size: 0.82em;
}

.hybrid-tool-icon {
  color: var(--cyan);
}

.tool-metric {
  color: #929298;
  font-size: 0.85em;
}

.hybrid-tool-details {
  display: grid;
  width: min(100%, 105ch);
  gap: 1px;
  margin: 0 0 17px 3ch;
}

.hybrid-tool-details > div {
  display: grid;
  grid-template-columns: 3ch 27ch 1fr;
}

.hybrid-change {
  width: min(100%, 108ch);
  margin-bottom: 18px;
  border: 1px solid rgba(255, 255, 255, 0.1);
  background: rgba(17, 17, 17, 0.18);
}

.hybrid-change-head {
  display: flex;
  justify-content: space-between;
  padding: 7px 10px;
  border-bottom: 1px solid rgba(255, 255, 255, 0.08);
}

.hybrid-diff-grid {
  display: grid;
  grid-template-columns: 6ch 1fr;
  padding: 6px 0;
}

.hybrid-diff-grid > span {
  padding: 1px 1ch;
}

.hybrid-diff-grid .line-no {
  color: #65656a;
  text-align: right;
  user-select: none;
}

.hybrid-diff-grid .diff-removed { background: rgba(255, 107, 107, 0.07); }
.hybrid-diff-grid .diff-added { background: rgba(77, 255, 136, 0.065); }

.hybrid-answer {
  display: grid;
  max-width: 105ch;
  grid-template-columns: 2ch 1fr;
  gap: 0.5ch;
}

.hybrid-submitted {
  border-left: 2px solid var(--cyan);
}

.hybrid-rail {
  padding: 18px 16px;
  border-left: 1px solid rgba(255, 255, 255, 0.11);
  background: rgba(17, 17, 17, 0.26);
  color: #a9a9ae;
  font-size: 0.82em;
}

.rail-title {
  display: flex;
  justify-content: space-between;
  margin-bottom: 13px;
  color: var(--white);
  letter-spacing: 0.1em;
}

.context-ring {
  display: grid;
  width: 76px;
  height: 76px;
  place-content: center;
  margin: 4px auto 21px;
  border-radius: 50%;
  background:
    radial-gradient(circle, rgb(31, 31, 34) 57%, transparent 59%),
    conic-gradient(var(--cyan) calc(var(--progress) * 1%), rgba(255, 255, 255, 0.1) 0);
  color: var(--white);
  text-align: center;
}

.context-ring span,
.context-ring small {
  display: block;
}

.context-ring small {
  color: var(--muted);
  font-size: 0.66em;
}

.rail-section {
  display: grid;
  gap: 4px;
  margin-top: 16px;
}

.rail-label {
  margin-bottom: 3px;
  color: #66666c;
  font-size: 0.78em;
  letter-spacing: 0.12em;
}

.rail-plan,
.rail-hooks > div,
.rail-section > div {
  display: flex;
  justify-content: space-between;
  gap: 1ch;
}

.rail-plan.active { color: var(--bright-cyan); }
.rail-plan .done { color: var(--green); }

.hybrid-bottom {
  padding: 0 14px 9px;
}

.hybrid-composer {
  display: grid;
  min-height: 66px;
  grid-template-columns: 3ch 1fr auto auto;
  align-items: start;
  gap: 1ch;
  padding: 11px 13px;
  border: 1px solid rgba(94, 252, 255, 0.36);
  border-radius: 5px;
  background: rgba(255, 255, 255, 0.055);
  box-shadow: inset 3px 0 var(--cyan);
}

.composer-chip {
  margin-top: 1px;
}

.composer-chip.warm {
  border-color: rgba(232, 121, 81, 0.43);
  color: var(--claude-soft);
}

.hybrid-footer {
  display: flex;
  gap: 1.25ch;
  padding: 6px 3px 0;
  color: #77777d;
  font-size: 0.86em;
  white-space: nowrap;
}

.branch { color: var(--red); }
.footer-separator { color: #4f4f54; }

/* Prototype controls and Pi hook inspection */

.prototype-switcher {
  position: fixed;
  z-index: 20;
  bottom: 20px;
  left: 50%;
  display: grid;
  width: min(780px, calc(100vw - 30px));
  min-height: 60px;
  grid-template-columns: 44px minmax(220px, 1fr) auto auto 44px;
  align-items: center;
  gap: 9px;
  padding: 7px;
  border: 1px solid rgba(255, 255, 255, 0.17);
  border-radius: 14px;
  background: rgba(15, 15, 17, 0.9);
  box-shadow: 0 16px 40px rgba(0, 0, 0, 0.45);
  translate: -50% 0;
  backdrop-filter: blur(20px);
  font: 500 12px/1.2 ui-sans-serif, system-ui, sans-serif;
}

.prototype-switcher button {
  min-height: 42px;
  border: 0;
  border-radius: 9px;
  background: rgba(255, 255, 255, 0.065);
  cursor: pointer;
}

.prototype-switcher button:hover,
.prototype-switcher button:focus-visible {
  background: rgba(255, 255, 255, 0.13);
  outline: 1px solid rgba(255, 255, 255, 0.18);
}

.variant-copy {
  display: grid;
  gap: 3px;
  min-width: 0;
}

.variant-copy strong {
  color: #f2f2f3;
}

.variant-copy span {
  overflow: hidden;
  color: #8d8d93;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.variant-dots {
  display: flex;
  gap: 5px;
}

.variant-dots span {
  width: 5px;
  height: 5px;
  border-radius: 50%;
  background: #55555b;
}

.variant-dots span.active {
  background: var(--white);
  box-shadow: 0 0 8px rgba(255, 255, 255, 0.4);
}

.prototype-switcher .hook-toggle {
  min-width: 108px;
  padding-inline: 12px;
}

.prototype-switcher .hook-toggle.active {
  background: rgba(94, 252, 255, 0.12);
  color: var(--bright-cyan);
}

.variant-mobile-label {
  display: none;
}

.is-inspecting [data-hook] {
  position: relative;
  outline: 1px dashed rgba(94, 252, 255, 0.52);
  outline-offset: 3px;
}

.is-inspecting [data-hook]::after {
  position: absolute;
  z-index: 10;
  top: -10px;
  right: 3px;
  max-width: 42ch;
  padding: 1px 6px;
  border: 1px solid rgba(94, 252, 255, 0.32);
  border-radius: 2px;
  background: #101317;
  color: var(--bright-cyan);
  content: attr(data-hook);
  font: 600 9px/1.45 ui-monospace, monospace;
  letter-spacing: 0.02em;
  pointer-events: none;
  white-space: nowrap;
}

@media (max-width: 1050px) {
  .prototype-page { padding-inline: 12px; }
  .ghostty-window { width: calc(100vw - 24px); }
  .prototype-caption { width: calc(100vw - 24px); }
  .ghostty-screen { font-size: 14px; }
  .hybrid-body { grid-template-columns: 1fr; }
  .hybrid-rail { display: none; }
  .codex-header { min-width: 75%; }
}

@media (max-width: 700px) {
  .prototype-page { padding-top: 22px; padding-bottom: 105px; }
  .prototype-caption { display: none; }
  .ghostty-window { height: calc(100vh - 128px); min-height: 500px; border-radius: 9px; }
  .ghostty-titlebar { grid-template-columns: auto 1fr auto; }
  .ghostty-tab { justify-self: center; }
  .ghostty-screen { font-size: 12px; }
  .codex-header { min-width: 100%; }
  .codex-header-grid { grid-template-columns: max-content 1fr; }
  .codex-header-grid > :nth-child(3),
  .codex-header-grid > :nth-child(4) { display: none; }
  .codex-footer > :nth-child(2),
  .codex-footer > :nth-child(4),
  .claude-footer > :nth-child(4),
  .hybrid-header-center,
  .hybrid-footer > :nth-child(n + 5) { display: none; }
  .claude-header { grid-template-columns: 1fr; }
  .claude-welcome-right { display: none; }
  .hybrid-header { grid-template-columns: 1fr auto; }
  .hybrid-header-right { grid-column: 2; }
  .prototype-switcher { grid-template-columns: 42px 1fr auto 42px; }
  .variant-dots { display: none; }
  .prototype-switcher .hook-toggle { min-width: 72px; font-size: 0; }
  .prototype-switcher .hook-toggle::after { content: "Hooks"; font-size: 11px; }
}

@media (prefers-reduced-motion: reduce) {
  .wallpaper span { animation: none; }
}

