   12 function applyMarkdownTransformers(
   13 	markdown: string,
   14 	context: MarkdownTransformContext,
   15 	transformers: readonly MarkdownTransformer[],
   16 ): string {
   17 	let transformedMarkdown = markdown;
   18 	for (const transformer of transformers) {
   19 		try {
   20 			const transformed = transformer(transformedMarkdown, context);
   21 			if (typeof transformed === "string") {
