   74  * Render a diff string with colored lines and intra-line change highlighting.
   75  * - Context lines: dim/gray
   76  * - Removed lines: red, with inverse on changed tokens
   77  * - Added lines: green, with inverse on changed tokens
   78  */
   79 export function renderDiff(diffText: string, _options: RenderDiffOptions = {}): string {
   80 	const lines = diffText.split("\n");
   81 	const result: string[] = [];
   82 
   83 	let i = 0;
   84 	while (i < lines.length) {
   85 		const line = lines[i];
   86 		const parsed = parseDiffLine(line);
   87 
   88 		if (!parsed) {
   89 			result.push(theme.fg("toolDiffContext", line));
   90 			i++;
   91 			continue;
   92 		}
   93 
   94 		if (parsed.prefix === "-") {
   95 			// Collect consecutive removed lines
   96 			const removedLines: { lineNum: string; content: string }[] = [];
   97 			while (i < lines.length) {
   98 				const p = parseDiffLine(lines[i]);
   99 				if (!p || p.prefix !== "-") break;
  100 				removedLines.push({ lineNum: p.lineNum, content: p.content });
  101 				i++;
  102 			}
  103 
  104 			// Collect consecutive added lines
  105 			const addedLines: { lineNum: string; content: string }[] = [];
  106 			while (i < lines.length) {
  107 				const p = parseDiffLine(lines[i]);
  108 				if (!p || p.prefix !== "+") break;
  109 				addedLines.push({ lineNum: p.lineNum, content: p.content });
  110 				i++;
  111 			}
  112 
  113 			// Only do intra-line diffing when there's exactly one removed and one added line
  114 			// (indicating a single line modification). Otherwise, show lines as-is.
  115 			if (removedLines.length === 1 && addedLines.length === 1) {
  116 				const removed = removedLines[0];
  117 				const added = addedLines[0];
  118 
  119 				const { removedLine, addedLine } = renderIntraLineDiff(
  120 					replaceTabs(removed.content),
  121 					replaceTabs(added.content),
  122 				);
  123 
  124 				result.push(theme.fg("toolDiffRemoved", `-${removed.lineNum} ${removedLine}`));
  125 				result.push(theme.fg("toolDiffAdded", `+${added.lineNum} ${addedLine}`));
  126 			} else {
  127 				// Show all removed lines first, then all added lines
  128 				for (const removed of removedLines) {
  129 					result.push(theme.fg("toolDiffRemoved", `-${removed.lineNum} ${replaceTabs(removed.content)}`));
  130 				}
  131 				for (const added of addedLines) {
  132 					result.push(theme.fg("toolDiffAdded", `+${added.lineNum} ${replaceTabs(added.content)}`));
  133 				}
  134 			}
  135 		} else if (parsed.prefix === "+") {
  136 			// Standalone added line
  137 			result.push(theme.fg("toolDiffAdded", `+${parsed.lineNum} ${replaceTabs(parsed.content)}`));
  138 			i++;
  139 		} else {
  140 			// Context line
  141 			result.push(theme.fg("toolDiffContext", ` ${parsed.lineNum} ${replaceTabs(parsed.content)}`));
  142 			i++;
  143 		}
  144 	}
